        $bd = $it['tier'] === 'single' ? $E['k_single'] . ($it['price'] > 0 ? ' · ' . rtrim(rtrim(number_format((float)$it['price'], 2, '.', ''), '0'), '.') . ' ' . $cur : '') : $E['k_' . $it['tier']];
        echo '<a class="card rv lmv" href="market.php?lang=' . h($lang) . '" style="padding:0;overflow:hidden;text-decoration:none;color:inherit"><div class="mvv" data-w="' . (int)$it['pw'] . '" data-h="' . (int)$it['ph'] . '" style="position:relative;aspect-ratio:16/9;background:#050913;overflow:hidden">' . ($pv ? '<button type="button" class="lxp" title="⛶">⛶</button><iframe sandbox="allow-scripts" data-src="' . h($pv) . '" tabindex="-1" style="position:absolute;border:0;transform-origin:0 0;pointer-events:none" title="' . h($it['title']) . '"></iframe>' : '') . '</div><div style="padding:14px 16px"><b>' . h($it['title']) . '</b><div style="color:var(--mut);font-size:13px;margin-top:4px">' . h($bd) . ' · ' . h(strtoupper($it['format'])) . ' · ' . h($it['resolution']) . '</div></div></a>';
    }
    if (!$mk) echo '<p style="grid-column:1/-1;text-align:center;color:var(--mut)">' . h($E['k_none']) . '</p>';
    echo '</div><div class="use">'; foreach ($E['use'] as $u) echo '<div><b>' . h($u[0]) . '</b>' . h($u[1]) . '</div>'; echo '</div><p style="text-align:center;margin-top:22px"><a class="btn" href="market.php?lang=' . h($lang) . '">' . h($E['k_all']) . '</a></p><p style="text-align:center;color:var(--mut);margin-top:16px">' . h($E['k_each']) . '<br><small>' . h($E['k_lic']) . '</small></p></div></section>';
    echo '<style>.lxp{position:absolute;right:8px;top:8px;z-index:3;background:rgba(5,11,24,.78);border:1px solid #2a4a7a;color:#fff;border-radius:8px;width:32px;height:32px;cursor:pointer}.lmv .mvv{cursor:zoom-in}
#lpop{position:fixed;inset:0;z-index:99990;background:rgba(2,6,14,.9);display:none;align-items:center;justify-content:center;padding:3vh 3vw}#lpop.on{display:flex}
#lbox{background:#080f20;border:1px solid #2a4a7a;border-radius:16px;width:min(1280px,100%);overflow:hidden}#lbar{display:flex;gap:8px;align-items:center;padding:10px 14px;color:#f4f7ff}#lbar b{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#lbar button,#lbar a{background:#10213a;border:1px solid #2a4a7a;color:#fff;border-radius:8px;padding:6px 12px;cursor:pointer;text-decoration:none;font-size:14px}
#lst{position:relative;width:100%;background:#000;overflow:hidden}#lst iframe{position:absolute;border:0;transform-origin:0 0;background:transparent}#lst:fullscreen{width:100vw;height:100vh;aspect-ratio:auto!important}</style>
<div id="lpop"><div id="lbox"><div id="lbar"><b id="ltt"></b><button id="lrp" type="button">↻</button><button id="lfs" type="button">⛶</button><a id="lgo" href="market.php?lang=' . h($lang) . '">Market →</a><button id="lcl" type="button">✕</button></div><div id="lst"></div></div></div>
<script>(function(){var P=document.getElementById("lpop"),S=document.getElementById("lst"),fr=null,cu=null;
function fit(){if(!fr)return;var k=Math.min(S.clientWidth/cu.w,S.clientHeight/cu.h);fr.style.width=cu.w+"px";fr.style.height=cu.h+"px";fr.style.transform="scale("+k+")";fr.style.left=(S.clientWidth-cu.w*k)/2+"px";fr.style.top=(S.clientHeight-cu.h*k)/2+"px"}
function close(){if(document.fullscreenElement)document.exitFullscreen();P.classList.remove("on");S.innerHTML="";fr=null}
document.addEventListener("click",function(e){var m=e.target.closest(".lmv .mvv");if(m){var f=m.querySelector("iframe");e.preventDefault();if(!f)return;var c=m.closest(".lmv");cu={w:+m.dataset.w||1280,h:+m.dataset.h||720,src:f.dataset.src};S.style.aspectRatio=cu.w+"/"+cu.h;S.innerHTML="";fr=document.createElement("iframe");fr.setAttribute("sandbox","allow-scripts");fr.src=cu.src;S.appendChild(fr);document.getElementById("ltt").textContent=c.querySelector("b").textContent;P.classList.add("on");setTimeout(fit,30);return}
 if(e.target.id==="lcl"||e.target===P)close();else if(e.target.id==="lrp"&&fr)fr.src=cu.src+"?"+Date.now()%1e6;else if(e.target.id==="lfs"){if(document.fullscreenElement)document.exitFullscreen();else S.requestFullscreen&&S.requestFullscreen()}},true);
document.addEventListener("keydown",function(e){if(e.key==="Escape"&&P.classList.contains("on"))close()});addEventListener("resize",fit);document.addEventListener("fullscreenchange",function(){setTimeout(fit,60)})})()</script>';
    echo '<script>(function(){function f(v){var i=v.querySelector("iframe");if(!i)return;var w=+v.dataset.w||1280,h=+v.dataset.h||720,k=Math.min(v.clientWidth/w,v.clientHeight/h);i.style.width=w+"px";i.style.height=h+"px";i.style.transform="scale("+k+")";i.style.left=(v.clientWidth-w*k)/2+"px";i.style.top=(v.clientHeight-h*k)/2+"px"}var vs=document.querySelectorAll(".mvv");vs.forEach(function(v){var i=v.querySelector("iframe");if(i){if("IntersectionObserver"in window){new IntersectionObserver(function(es,o){es.forEach(function(e){if(e.isIntersecting){i.src=i.dataset.src;f(v);o.disconnect()}})},{rootMargin:"200px"}).observe(v)}else i.src=i.dataset.src}f(v)});addEventListener("resize",function(){vs.forEach(f)})})()</script>';
}
